  "landing.ebEdu": "EDUCATION MODE",
  "landing.eduH": "Education is being built on top of Basic.",
  "landing.eduP": "A student-exercise layer built on the same Kết cấu-analysis engine. Teachers write exercises inside the app, hand them out as a link and get the answers back; what is still missing is the layer above that — the course.",
  "landing.eduNowKicker": "WORKS TODAY",
  "landing.eduNowTitleNew": "The student exercise layer",
  "landing.eduNow1": "Seven predefined exercises, grouped into statics, strength and advanced.",
  "landing.eduNow2": "The model Tải trọng and solves automatically. Correct answers come from the solver, not from a stored answer key.",
  "landing.eduNow3": "Questions on Phản lực, on diagram values and shapes, on kinematics (isostatic or hyperstatic, and the degree) and on Tiết diện data.",
  "landing.eduNow4": "The student DRAWS the diagram — the ordinates, and the power of each span — and the drawing and the powers are marked separately against the solve. Shear, moment, axial and the deflected shape.",
  "landing.eduNow5": "Answers are checked within a tolerance, with a hint when the sign or the order of magnitude is what went wrong. Kết quả stay hidden while you work; whether they can be revealed at all is the teacher's decision.",
  "landing.eduNow6": "A teacher writes an exercise in the app: draw the structure with the usual tools, then say what to ask about it. No code, no files to edit.",
  "landing.eduNow7": "Handing out is a link or a file, and it opens a workspace built for the student. They hand back a file or a short code, and the teacher opens it as a marked table.",
  "landing.eduNextKicker": "IN DEVELOPMENT",
