  "landing.eduNext3": "Student workflows for inspecting, repairing and building models, rather than only reading one.",
  "landing.eduNext4": "A course-shaped progression: stability, Phản lực, displacements, diagrams, kinematics, Phân tích tiết diện.",
  "landing.eduNext5": "Terminology Trợ giúp where a student meets a word for the first time.",
  "landing.eduNext6": "Separate onboarding for teachers and for students.",
  "landing.eduNotYet": "What exists is the exercise and the round trip around it: a teacher writes one, hands it out, and reads the answers back. What does not exist is the course around THAT — assignments, a class list, attempts, a mark that lives anywhere. Stabileo stores nothing on a server, so an exercise and a submission travel as a link, a file or a code, the way work is already handed in. The step-by-step stiffness-method lessons are available as part of Basic.",
