  "landing.proNextTitle": "What PRO is still missing",
  "landing.proNext1": "Complete, structure-wide reinforcement detailing.",
  "landing.proNext2": "Full floor-plan drawings: setting-out and reinforcement for a whole floor.",
  "landing.proNext3": "Code-verified reinforcement across every supported family, as today’s provisional Kết quả are promoted with published benchmarks.",
  "landing.proNext4": "Production-ready Xuất of complete Kết cấu plans and schedules straight out of Stabileo.",
  "landing.proNext5": "Seismic workflows to INPRES-CIRSOC 103.",
  "landing.cirsocP": "Stabileo is built in Argentina, so CIRSOC comes first: it is the Argentine regulatory framework and the one this work answers to, and it is where code-based design is furthest along. The roadmap continues with the Eurocodes, and then with the United States codes.",
  "landing.cir101Scope": "Permanent and imposed Tải trọng, and Các tổ hợp tải trọng",
  "landing.cir101Body": "Generated from the model: self weight, partition allowance, the minimum imposed Tải trọng of Table 4.1, live-Tải trọng reduction, and the seven strength combinations verbatim.",
  "landing.cir101Limit": "Further Tải trọng types will follow.",
  "landing.cir102Scope": "Wind action",
  "landing.cir102Body": "Velocity pressure, exposure and terrain constants, topography, gust effect, enclosure classification and the wall and roof pressure coefficients, applied to the main wind-force resisting system.",
  "landing.cir102Limit": "Non-rigid buildings and torsional Các trường hợp tải will be added.",
  "landing.cir201Scope": "Reinforced-concrete design, and reinforcement generation",
  "landing.cir201Body": "The strongest coverage of any code here. Beams and columns are both verified and generated: flexure, shear, ties, bar regions, spacing, anchorage and lap lengths, each result carrying its clause. Slabs, walls and pad footings are designed too, reachable from the workflow, and their Kết quả are labelled provisional.",
  "landing.cir201Limit": "Finishing development, and being tested against real projects.",
  "landing.cir301Scope": "Steel Thanh checking",
  "landing.cir301Body": "A checker for steel Các thanh on the AISC 360 LRFD basis: Kéo, Nén, flexure with lateral-torsional Mất ổn định / Oằn, shear and combined actions.",
  "landing.cir301Limit": "Code-based design in development.",
  "landing.cir103Scope": "Seismic action and seismic detailing",
  "landing.cir103Body": "Effective seismic weight and the static-method distribution of base shear up the height are already generated.",
  "landing.cir103Limit": "Code-based seismic workflow in development.",
  "landing.codesIntlTitle": "INTERNATIONAL CODES · Thanh CHECKING",
  "landing.aiStatus": "Stabileo AI is in active development. The agent routes already run in development and testing against a dedicated backend, on the same solver and the same numbers as everything else on this page. That backend is not part of the public site yet, so this Tiết diện describes the direction rather than a service you can Mở today. The engineer still signs the work.",
  "landing.aiFutKicker": "IN DEVELOPMENT",
  "landing.aiFutTitle": "What the agent layer will do",
  "landing.aiFut1": "Trợ giúp create and modify Kết cấu models.",
  "landing.aiFut2": "Interpret Kết cấu Kết quả.",
  "landing.aiFut3": "Explain engineering concepts and what the solver returned.",
  "landing.aiFut4": "Assist through a design workflow.",
  "landing.aiFut5": "Gối tựa code-aware Kết cấu decisions.",
  "landing.aiFut6": "Connect modelling, verification and documentation.",
  "landing.badgeDev": "IN DEVELOPMENT",
  "landing.stGroupDev": "In development",
  "landing.stD4": "INPRES-CIRSOC 103 seismic — Tải trọng generation today, the full code workflow in development",
  "landing.accessEdu": "The core application is intended to stay free for educational use, and the Education and PRO layers grow on top of it.",
  "landing.stPa3": "Reinforcement drawings and bar schedules for beams, columns, footings, slabs and walls, exporting to DXF, SVG and XLSX; structure-wide plans in development",
  "landing.stPa4": "Kết quả are labelled provisional until an independent external benchmark is on file",
  "landing.stD1": "Education mode — the exercise and the round trip around it run; the course above them is in development",
  "landing.stD2": "PRO mode — advanced analysis and concrete design today, detailing and Xuất expanding",
  "landing.stD3": "Stabileo AI — the agent layer, in development on the same solver",
  "landing.proNow6": "One-way and two-way slabs, walls and pad footings are designed too, from a real command in the workflow. These Kết quả are labelled provisional while they are tested against real projects.",
  "landing.proNow7": "Reinforcement drawings for five Phần tử families: beam and column elevations with their Tiết diện, footing plans with two Tiết diện, slab panel plans, and wall elevations and Tiết diện. They Xuất as DXF and SVG.",
  "landing.proNow8": "A bar bending schedule with marks, diameters, shapes, quantities, cutting lengths measured along the physical bar including its hook arcs, mass, commercial stock bars and offcuts, plus a note wherever a bar exceeds stock length and needs a splice. It exports to XLSX.",
  "landing.proNext6": "Torsion, beam-column joints, diaphragms and non-rectangular Tiết diện.",
  "landing.stPa5": "Slabs, walls and pad footings are designed and reachable in the workflow, and are being tested against real projects",
  "landing.modesLead": "All four grow on the same solver. Basic is the Kết cấu-analysis mode you can use today; Education, PRO and Stabileo AI extend it with learning, advanced engineering and agent workflows.",
  "landing.proNext7": "International code Gối tựa, after CIRSOC.",
  "landing.badgeTesting": "PARTIAL · IN TESTING",
  "landing.codesLead": "Thanh checking already spans the main international codes. Code-based design, meaning proposing a design and generating reinforcement, is being built out one framework at a time.",
  "landing.codesIntlLead": "The solver rates a Thanh you designed against each of these today.",
  "landing.codesRegionUs": "United States",
  "landing.codesRegionEu": "Europe",
  "landing.basicPt6": "Live re-Đang giải, as an option: switch it on and the solver runs on every edit, so the diagrams follow the model while you change it.",
  "landing.codeTimberMasonry": "Timber and masonry",
