  "advanced.slidingUnsupported": "Sliding joints are supported for linear static analysis and free-body view. This advanced analysis does not yet include sliding-joint constraints, so Kết quả would be too stiff. Remove sliding joints or use linear analysis.",
  "advanced.sliding3dUnsupported": "Sliding joints are currently supported only in 2D linear static analysis and free-body view. 3D analysis does not yet include sliding-joint constraints.",
  "advanced.jointsUnsupported": "Internal 3D joints are included only in linear static analysis and free-body view. This advanced analysis does not yet include joint releases, so Kết quả would be too stiff. Remove the joints or use linear analysis.",
  "advanced.runDynamicFirst": "Run dynamic analysis (modal) first",
  "advanced.defineCombosFirst": "Define combinations first in the Combinations tab",
  "advHelp.pdelta.label": "P-\\u0394 (2nd Order)",
  "advHelp.pdelta.text": "Geometric nonlinear analysis. Considers how axial forces modify the lateral stiffness of the structure (P-\\u0394 effect). Iterates until convergence and reports the amplification factor B\\u2082. If B\\u2082 > 1.4, the structure is sensitive to second-order effects. Requires Đang giải first.",
  "advHelp.buckling.label": "Pcr \\u2014 Critical Tải trọng (Euler)",
  "advHelp.buckling.text": "Computes the elastic Mất ổn định / Oằn Tải trọng via eigenvalues of the geometric stiffness matrix. The factor \\u03BB_cr indicates how much the current Tải trọng would need to be multiplied for the structure to buckle. If \\u03BB_cr < 1, the structure has already exceeded its critical Tải trọng. Shows the effective length (Keff) of each compressed Thanh.",
  "advHelp.modal.label": "Dynamic Analysis (Modal)",
  "advHelp.modal.text": "Computes vibration modes and natural frequencies using the consistent mass matrix. Reports: frequency (Hz), period (s), effective modal mass (%) in X and Y, and Rayleigh damping coefficients. Prerequisite for spectral analysis. Requires Vật liệu density (\\u03C1).",
  "advHelp.spectral.label": "Spectral Analysis (CIRSOC 103)",
  "advHelp.spectral.text": "Modal spectral combination with CIRSOC 103 seismic design spectrum (Argentina). Computes base shear, displacements, and peak forces by combining modes using CQC or SRSS. Requires running dynamic analysis first. Uses Zone 4, Soil type II by default.",
  "advHelp.plastic.label": "Plastic Collapse",
  "advHelp.plastic.text": "Incremental analysis that forms plastic hinges at points where the moment reaches Mp (plastic moment = Wpl \\u00D7 fy). At each step, the structure is recalculated with the new hinge. The factor \\u03BB indicates how much to multiply the Tải trọng to reach the collapse mechanism. Requires Vật liệu fy.",
  "advHelp.dsm.label": "Step by Step \\u2014 Phương pháp độ cứng trực tiếp",
  "advHelp.dsm.text": "Shows each step of the Phương pháp độ cứng trực tiếp in detail: DOF numbering, local stiffness matrices [k], transformations [T], global assembly [K], Tải trọng vector {F}, boundary conditions, system solution {u} = [K]\\u207B\\u00B9{F}, and extraction of Phản lực and Nội lực. Ideal for studying and learning the method.",
  "advHelp.envelope.label": "Force Envelope",
  "advHelp.envelope.text": "Force envelope from Các tổ hợp tải trọng. Solves each Trường hợp tải separately and combines them with the factors defined in the combinations table (e.g., 1.2D + 1.6L). Shows the maximum and minimum (+/\\u2212) envelope of moment, shear, and Lực dọc. Allows comparing individual combinations from the \"Primary\" dropdown in Cài đặt \\u2192 Kết quả. Requires combinations defined in the \"Combinations\" tab.",
  "advHelp.trainLoad.label": "Tải trọng di động",
  "advHelp.trainLoad.text": "A Tải trọng train (e.g., HL-93 truck, tandem) traverses the structure at multiple positions. At each position, the full structure is Đã giải and forces are recorded. Train Tải trọng are ADDED to existing model Tải trọng \\u2014 to see only the train effect, remove other Tải trọng. After Đang giải, use the \\u25C0\\u25B6 arrows to step through positions and \"View envelope\" to see the maximum and minimum forces across all positions. Classic tool for bridge and vehicular Tải trọng design.",
  "advHelp.influenceLine.label": "Influence Line",
  "advHelp.influenceLine.text": "Shows how a fixed quantity (reaction, moment, or shear at a specific Tiết diện) varies when a unit Tải trọng P=1 traverses the structure. Click a Nút to see the IL of its Phản lực (Ry, Rx, Mz) or a Thanh for M or V at that Tiết diện. Classic tool for bridge and Tải trọng di động design. Shortcut: key I.",
  "advHelp.despiece.label": "Free-body view (despiece)",
  "advHelp.despiece.text": "Educational view that pulls each Thanh off its joints and draws the internal end forces it transmits — axial N, shear V and moment M — plus Gối tựa Phản lực. Các thanh sharing a joint show equal/opposite action–reaction pairs across the gap. Requires a Đã giải model; uses the current Kết quả. Visualization only — it does not change the model or run a new analysis.",
  "advHelp.kinematic.label": "Phân tích động học",
  "advHelp.kinematic.text": "Step-by-step analysis of the kinematic stability of the structure. Shows the degree of static indeterminacy (detailed formula with each Gối tựa and hinge), numerically verifies via Kff rank if hidden mechanisms exist, and suggests corrections if the structure is unstable. Works without Đang giải \\u2014 updates in real time as the model is modified.",
  "advHelp.stress.label": "Stress \\u2014 Phân tích tiết diện",
  "advHelp.stress.text": "Complete stress analysis of cross-Tiết diện. Click a Thanh to see: normal stress \\u03C3 (Navier: \\u03C3 = N/A + M\\u00B7y/I), shear stress \\u03C4 (Jourawski: \\u03C4 = V\\u00B7Q/(I\\u00B7b)), Von Mises equivalent stress (\\u03C3_vm = \\u221A(\\u03C3\\u00B2 + 3\\u03C4\\u00B2)), Mohr\\'s circle with principal stresses, shear flow diagram for thin-walled profiles, and utilization ratio vs fy. Includes a slider to traverse Tiết diện fibers (0=bottom, 1=top) and navigation to critical Tiết diện (max moment, Gối tựa, Tải trọng points). Gối tựa rectangular, I, U, L, box (RHS), and tubular (CHS) Tiết diện.",
  "advHelp.whatif.label": "Explore (What if\\u2026?)",
  "advHelp.whatif.text": "Interactive parametric sensitivity analysis panel. Adjust Tải trọng magnitudes, Vật liệu elastic modulus E, and Tiết diện Thuộc tính (area A and inertia Iz) in real time using sliders. The structure recalculates instantly with each change (~60ms) showing how diagrams, deformed shapes, and Phản lực vary. Ideal for understanding Kết cấu behavior, optimizing Tiết diện, and answering questions like \"what if I double the Tải trọng?\" or \"what if I use a stiffer profile?\". Changes are temporary \\u2014 the original model is restored when the panel is closed.",
  "examples.title": "Examples",
