  "tooltip.toolSelect.title": "Select (V)",
  "tooltip.toolSelect.desc": "Has 5 sub-modes: Các nút, Các thanh, Gối tựa, Tải trọng, and Stresses. Switch in the floating bar.",
  "tooltip.toolNode.title": "Create Nút (N)",
  "tooltip.toolNode.desc": "Click on the canvas to place a junction point. Các nút are where Các thanh connect and Tải trọng are applied.",
  "tooltip.toolElement.title": "Create Thanh (E)",
  "tooltip.toolElement.desc": "Click a start Nút, then an end Nút. A Thanh is created between them. Frame = rigid, Hệ dàn (Truss) = pinned.",
  "tooltip.toolSupport.title": "Create Gối tựa (S)",
  "tooltip.toolSupport.desc": "Click on a Nút to place a Gối tựa. The Gối tựa type determines which movements are restrained.",
  "tooltip.toolLoad.title": "Áp dụng Tải trọng (L)",
  "tooltip.toolLoad.desc": "Click on a Nút (point Tải trọng) or Thanh (distributed Tải trọng) to Áp dụng a force. Negative values = downward.",
  "tooltip.toolInfluence.title": "Influence Line (I)",
  "tooltip.toolInfluence.desc": "Shows how a reaction or force varies when a unit Tải trọng traverses the structure.",
  "tooltip.toolPan.title": "Pan View (H)",
  "tooltip.toolPan.desc": "Drag to move the view. You can also use middle-click or Ctrl+drag.",
  "tooltip.solve.title": "Solve",
  "tooltip.solve.desc": "Solves the structure using the Phương pháp độ cứng trực tiếp (DSM). Requires Các nút, Các thanh, Gối tựa, and Tải trọng.",
  "tooltip.selfweight.title": "Trọng lượng bản thân",
  "tooltip.selfweight.desc": "Automatically adds gravity distributed Tải trọng using the Vật liệu density and Tiết diện area.",
  "tooltip.diagNone.title": "No Diagram",
  "tooltip.diagNone.desc": "Hides all result diagrams. Only the structure is shown.",
  "tooltip.diagDeformed.title": "Đường biến dạng",
  "tooltip.diagDeformed.desc": "Shows the amplified Đường biến dạng. Useful for verifying that the behavior is reasonable.",
  "tooltip.diagMoment.title": "Mô-men uốn (M)",
  "tooltip.diagMoment.desc": "Diagram of the Mô-men uốn in each Thanh. Drawn on the Kéo side by convention.",
  "tooltip.diagShear.title": "Shear (V)",
  "tooltip.diagShear.desc": "Diagram of Lực cắt along each Thanh. Abrupt changes indicate point Tải trọng.",
  "tooltip.diagAxial.title": "Axial (N)",
  "tooltip.diagAxial.desc": "Diagram of Lực dọc. Positive = Kéo (Thanh stretches), negative = Nén.",
  "tooltip.diagAxialColor.title": "Axial Color (N\\u00B1)",
  "tooltip.diagAxialColor.desc": "Colors Các thanh by Lực dọc: red = Kéo, blue = Nén. Thickness proportional to magnitude.",
  "tooltip.diagColorMap.title": "Color Map",
  "tooltip.diagColorMap.desc": "Colors Các thanh by the selected force (moment, shear, axial, or \\u03C3/fy ratio) using a color scale.",
  "tooltip.supFixed.title": "Fixed",
  "tooltip.supFixed.desc": "Restrains horizontal Chuyển vị (ux), vertical (uy), and rotation (\\u03B8). No movement allowed.",
  "tooltip.supPinned.title": "Pinned",
  "tooltip.supPinned.desc": "Restrains ux and uy, but allows rotation. The Thanh can rotate freely at this point.",
  "tooltip.supRollerX.title": "Roller X",
  "tooltip.supRollerX.desc": "Only restrains uy (vertical). Allows horizontal movement and rotation. Typical \"roller\" Gối tựa.",
  "tooltip.supRollerY.title": "Roller Y",
  "tooltip.supRollerY.desc": "Only restrains ux (horizontal). Allows vertical movement and rotation.",
  "tooltip.supSpring.title": "Spring",
  "tooltip.supSpring.desc": "Elastic Gối tựa with configurable stiffness in each direction (kx, ky, k\\u03B8). Models soil or flexible connections.",
