  "kinematic.slideAxisNote": "Each sliding joint adds 1 to c. The axis (global X/Z or Thanh-local x/z) only sets which relative translation is released — not how many.",
  "kinematic.step2Title": "Step 2 \\u2014 Degree of Static Indeterminacy",
  "kinematic.step3Title": "Step 3 \\u2014 Verification with Stiffness Matrix",
  "kinematic.matrixExplanation": "Stabileo solves structures by assembling a <strong style=\"color:#ddd\">global stiffness matrix</strong>. Here we analyze that matrix ({n}\\u00D7{n}) to detect mechanisms that the Step 2 equation misses \\u2014 for example, when Gối tựa are poorly distributed or hinges create local instabilities.",
