  "stress.ccEqDesc": "For each extreme fiber at distance <em>d</em> from the centroid, the CC vertex is at:",
  "stress.ccEqWhere": "where W = Tiết diện modulus, A = area, I = moment of inertia, d = distance to extreme fiber.",
