  "stress.fiberYZ3dHelp": "Position on the Tiết diện Y and Z axes where stresses are evaluated.\\nY (depth): bending by My, uses Iy. Z (width): bending by Mz, uses Iz.\\nIn the default unrolled orientation Y is the strong axis; a Tiết diện roll rotates this.\\nThe yellow dot shows the selected fiber.",
  "stress.fiberY2dHelp": "Height within the Tiết diện where stresses are evaluated.\\ny = 0 is the center (neutral axis if N=0).\\nMove the slider to scan from bottom to top fiber.\\nAt the extremes, normal stresses are maximum and shear is minimum.",
