  "pro.shellInfoTitle": "How shells connect & transfer Tải trọng",
  "pro.shellInfoTransfer": "Shells couple to beams and columns ONLY through SHARED Các nút — there is no continuous shell-to-beam edge coupling. Tải trọng crosses only where a shell Nút and a beam Nút are the same Nút.",
  "pro.shellInfoMesh": "Meshing subdivides the slab/wall into smaller quads, creating MORE shell Các nút along every edge.",
  "pro.shellInfoSplit": "If those new edge Các nút are NOT shared with the beam, Tải trọng does not transfer continuously along that beam — only at the original corners. Keep “Split surrounding beams” ON (default): the generator splits each edge beam at the mesh Các nút so they share Các nút. Turn it off only if you will share/split Các nút yourself.",
  "pro.shellInfoSlab": "Manual route: subdivide the supporting beams first, then mesh the slab so its edge Các nút coincide with the beam Các nút (shared Nút IDs). Matching Các nút = connected; unmatched edges carry no Tải trọng between them.",
