  "conn.sec.bolts.title": "Bolts",
  "conn.sec.bolts.purpose": "Shear, Kéo, bearing and interaction of a bolt group. Experimental calculation.",
  "conn.sec.bolts.blocked": "Pick a joint from the list to compute on it.",
  "conn.sec.welds.title": "Welds",
  "conn.sec.welds.purpose": "Fillet weld: throat, capacity and size limits. Experimental calculation.",
  "conn.sec.welds.blocked": "Pick a joint from the list to compute on it.",
  "conn.sec.gaps.title": "Limitations and known gaps",
  "conn.sec.gaps.purpose": "What this screen computes and what it does not. Five gaps confirmed by reading the code.",
  "conn.joints.what": "Every Nút with two or more Các thanh meeting is detected. Detection is geometric: it does not tell a beam-column joint from a splice or a base, and it does not read end releases.",
  "conn.joints.membersTitle": "Các thanh meeting here",
  "conn.joints.metallic": "metallic",
  "conn.joints.nonMetallic": "non-metallic",
  "conn.joints.mixedNote": "Mixed joint: offered because at least one Thanh is metallic. The calculations below Áp dụng to the metallic part; the rest of the joint is not checked here.",
  "conn.bolts.grades": "Grades supported: 4.6, 5.6, 8.8 and 10.9, with Ft and Fv tabulated per CIRSOC 301 Table J.3.2.",
  "conn.bolts.resultsExplain": "φRn is the group design capacity (φ=0.75). Each percentage is demand over capacity; the largest of the four governs.",
  "conn.welds.explain": "a is the fillet leg and the throat is taken as 0.707·a. Fexx is the electrode strength (E70xx = 490 MPa). Plate thickness is used only for the minimum and maximum weld size limits.",
  "conn.experimentalCalc": "Experimental calculation: no tests, no mapped clauses and no external benchmark. It is not a certifiable verification.",
  "conn.gap.notCertifiable": "It is not a certifiable verification.",
  "conn.gap.exists": "Exists",
  "conn.gap.missing": "Missing",
  "conn.gap.affects": "Affects the result",
  "conn.gap.scope": "Configurations affected",
  "conn.gap.affectsYes": "Yes",
  "conn.gap.affectsNo": "No — no checker on this screen consumes the value",
  "conn.gap.baseMetal.title": "Base metal rupture, not checked",
  "conn.gap.baseMetal.exists": "The fillet weld capacity: effective throat, length factor and φRn of the filler Vật liệu.",
  "conn.gap.baseMetal.missing": "Base metal rupture. `checkFilletWeld` receives the plate thickness but not its Fu, so it never compares the weld against the plate it joins.",
  "conn.gap.baseMetal.scope": "Every weld. The risk grows the stronger the electrode is relative to the plate.",
  "conn.gap.baseMetal.note": "The weld can read OK while the plate is the weak link.",
  "conn.gap.boltGeometry.title": "Bolt group geometry, incomplete",
  "conn.gap.boltGeometry.exists": "One bolt\\'s capacity, multiplied by the declared count.",
  "conn.gap.boltGeometry.missing": "The layout of the group: rows, pitch, gauge, and the eccentricity of the Tải trọng about the group centroid.",
  "conn.gap.boltGeometry.scope": "Any eccentric group. A concentric, compact group is the only case the simplification does not penalise.",
  "conn.gap.boltGeometry.note": "The reported capacity is a ceiling: an eccentric group shares Tải trọng worse and reaches its limit sooner.",
  "conn.gap.torsion.title": "Torsion computed and not shown",
  "conn.gap.torsion.exists": "getJointForces computes Mx per Thanh and per end, alongside N, Vy, Vz, My and Mz.",
  "conn.gap.torsion.missing": "The Mx column in the forces table. The value is computed and then dropped when drawing.",
  "conn.gap.torsion.scope": "None, as far as the two checkers go: neither bolts nor welds consume Mx.",
  "conn.gap.torsion.note": "It is a gap in exposure, not in calculation: the number exists and is not shown.",
  "conn.gap.aluminium.title": "Aluminium outside the filter",
  "conn.gap.aluminium.exists": "The metallic-participation filter, over Các thanh classified as steel.",
  "conn.gap.aluminium.missing": "Aluminium. The filter uses isSteel(), and materialFamilyOf cannot tell aluminium from steel by the magnitude of fy until the Vật liệu declares its grade.",
  "conn.gap.aluminium.scope": "Models with aluminium Các thanh: their joints can fall outside this list even though the metallic inventory does list them.",
  "conn.gap.aluminium.note": "And the bolt and electrode tables are steel: applying them to aluminium would be wrong even if the joint appeared.",
  "conn.gap.fvExcl.title": "Threads excluded from the shear plane, untabulated for 4.6 and 5.6",
  "conn.gap.fvExcl.exists": "The threads-included value, for all four grades.",
  "conn.gap.fvExcl.missing": "The threads-excluded value for 4.6 and 5.6: the table carries it only for 8.8 and 10.9.",
  "conn.gap.fvExcl.scope": "Grades 4.6 and 5.6. Unticking \"threads in the shear plane\" does not change the number, and the checkbox does not say so on its own.",
  "conn.gap.fvExcl.note": "The degradation is silent: the result is computed anyway, with the more conservative value.",
