  "detailing.joint.assumedJd": "Internal elastic lever arm taken as jd = {ratio} d. §15.4.1.1 requires the Kéo and Nén forces generated by flexure without prescribing how to obtain jd; this is a value common for rectangular Tiết diện, not a regulatory one.",
