  "detailing.floorRun.wallMomentFromMembraneOnly": "Wall {Phần tử}: in-plane demands were taken from the membrane stresses, so the in-plane moment is reported as zero rather than derived.",
  "detailing.floorRun.perElementPanel": "Each shell Phần tử is designed as its own panel: the moment used is that Phần tử\\u2019s own, not a strip envelope across the mesh.",
