  "footing.ui.matConflicts": "Physical clashes involving the mat",
  "footing.ui.matConflictRow": "{a} / {b} — {cls}: measured {measured} mm against {required} mm required.",
  "footing.ui.matNoConflicts": "The clash check found no conflicts involving the mat. The {crossings} orthogonal X/Y crossings are contacts by design: §25.2.1 and §25.2.2 set Xóa sạch distances between PARALLEL bars — in one layer and between parallel layers — and an orthogonal grid is neither case.",
  "footing.ui.matPunchingMoment.NEGLIGIBLE": "Unbalanced moment at the connection Msc = {msc} kN·m (components {x} and {y}), below the {threshold} kN·m significance threshold: direct shear governs. This is not a §8.4.4.2 verification.",
  "footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_TRANSFER_NOT_EVALUATED": "PUNCHING NOT VERIFIED. The connection transfers an unbalanced moment Msc = {msc} kN·m (components {x} and {y}), above a {threshold} kN·m threshold, and the §8.4.4.2 eccentric-shear moment transfer is not implemented. The bottom mat IS verified; the footing as a whole is not.",
  "footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_NOT_FORMED": "PUNCHING NOT VERIFIED. The connection\\u2019s unbalanced moment could not be formed, so it is not claimed to be zero. Checking direct shear alone would pass a joint whose moment nobody evaluated.",
  "footing.ui.matGeometrySteps": "Physical geometry memo",
  "footing.ui.matAnchorageSteps": "Anchorage memo",
  "footing.record.flexureGeometryNotReconciled": "The bottom mat is DESIGNED and its physical geometry does NOT RECONCILE with the schedule: {findings} blocking finding(s). No bars are emitted, because a drawn mat that disagrees with the approved schedule would reach the model, the drawing and the Xuất describing reinforcement nobody designed. Flexure is not verified.",
  "footing.record.anchorageNotEvaluated": "There is no physical mat to measure, so the development of the bottom reinforcement was not evaluated. This is not an anchorage failure: it is the absence of the geometry it would be measured from.",
  "footing.record.topReinforcementNotEvaluated": "Footing {footing}: the TOP reinforcement was not evaluated. No authoritative calculation in this project shows it to be unnecessary, so neither is that claimed nor is any top steel designed. The bottom-mat verification stands; the footing is not fit for issue while this remains Mở.",
  "footing.geometry.noLayerOrder": "No physical layer order was established ({rationale}), so there is no elevation to draw the bars at. Drawing them at the conservative envelope depth would put steel in the model at an elevation nobody chose.",
  "footing.geometry.directionNotDesigned": "Direction {axis} is not designed ({status}), so no geometry is generated in either direction: §13.3.3 requires reinforcement both ways and half a mat is not a mat.",
  "footing.geometry.elevationMismatch": "Direction {axis}: the bar-axis elevation implies an effective depth of {implied} m and the design was made at {designed} m. The bar would be drawn at a depth other than the one it was designed for.",
  "footing.geometry.countMismatch": "Direction {axis}, region {region}: the schedule asks for {scheduled} bar(s) and the placement produced {placed}. Steel is not redistributed to make the drawing Đóng.",
  "footing.geometry.spacingMismatch": "Direction {axis}, region {region}: the placed spacing is {placed} mm and the scheduled one is {scheduled} mm.",
  "footing.geometry.sideCoverShort": "Direction {axis}, region {region}, bar {bar}: the side cover measured to the bar SURFACE is {measured} mm, less than the {required} mm required.",
  "footing.geometry.bottomCoverShort": "Direction {axis}, bar {bar}: the bottom cover measured to the surface is {measured} mm against the {required} mm required, and {toTop} mm remain to the top face.",
  "footing.geometry.outsideConcrete": "Direction {axis}, bar {bar}: the bar leaves the concrete by {over} mm.",
  "footing.geometry.duplicateBar": "Direction {axis}: bars {a} and {b} occupy the same position.",
  "footing.geometry.clearSpacingShort": "Direction {axis}: between bars {a} and {b} the Xóa sạch spacing is {measured} mm, less than the {required} mm of §25.2.1. This is the gap between adjacent §13.3.3.3 regions, which no single region lays out.",
  "footing.geometry.providedAsMismatch": "Direction {axis}: the generated bars provide {placed} cm² and the schedule states {scheduled} cm².",
  "footing.anchorage.insufficient": "Direction {axis}, Ø{diameter}: {required} mm of straight development are required and {available} mm are available from the column face to the physical bar end, on the {side} side — {short} mm short. No hook is invented and ld is not reduced.",
  "footing.anchorage.noGeometry": "There is no physical mat ({status}), so the length available from the critical Tiết diện cannot be measured.",
  "footing.record.flexureDesignedNotModeled": "The bottom mat is DESIGNED in both directions — demand, required steel, bar count and code-compliant spacing — and it is NOT MODELLED: no physical bars exist in the model, the schedule or the CAD hand-off. Flexure therefore remains unverified, because there is still no reinforcement to verify the demand against.",
  "footing.record.flexureDesignFailed": "The bottom-mat design FAILED: no admissible reinforcement layout was found for this footing at the selected diameters. The named conditions say which requirement could not be met. The selected diameter was not changed silently and no layout is reported as acceptable.",
