  "footing.cad.interface.intentionalPassage": "These bars deliberately cross the footing-to-column interface. The crossing is the detail working as designed and must not be reported as a containment or cover failure.",
  "footing.cad.derivation.columnStub": "Column stub for Phần tử {Phần tử}: {B} × {L} m in plan from the Phần tử Tiết diện, from the footing top at z = {base} m up to z = {top} m. The upper plane is the top of the production transfer cage ({cageTop} m), truncated so it never exceeds the column top ({columnTop} m).",
  "footing.cad.cover.placementIntent": "Footing cover as the model carries it. This is the placement input the bars were positioned from, not a measured or verified Xóa sạch cover.",
  "footing.cad.check.collision": "Bar-to-bar interference, from the production collision detector.",
