  "footing.cad.check.footingCover": "Concrete cover inside the footing.",
  "footing.cad.check.columnCover": "Concrete cover inside the column stub.",
  "footing.cad.check.containment": "Whether the reinforcement lies inside the footing concrete.",
  "footing.cad.notEvaluated.footingCover": "Footing {footing}: Stabileo does not measure achieved cover. Cover is a placement input and no production code path checks the resulting geometry, so there is no cover verdict to report.",
  "footing.cad.notEvaluated.columnCover": "Phần tử {Phần tử}: column cover is out of scope for this release. The footing cover value does not Áp dụng to the column stub and must not be measured against it.",
  "footing.cad.notEvaluated.containment": "Footing {footing}: Stabileo has no production geometric containment check, for any Phần tử type, so containment is not evaluated.",
  "footing.cad.unsupported.matGeometry": "Footing {footing}: the bottom and top mats are drawing requirements, not bar geometry. This handoff carries the column-transfer cage only and is not complete footing reinforcement.",
  "footing.cad.unsupported.containment": "Footing {footing}: reinforcement containment is not evaluated by Stabileo. An external measurement is an independent observation and never a Stabileo verdict.",
  "footing.cad.unsupported.columnCover": "Phần tử {Phần tử}: column cover is neither required nor evaluated here.",
  "footing.cad.assumption.stubTruncated": "The column stub for Phần tử {Phần tử} is truncated at z = {top} m, the top of the transfer cage. That upper face is a cut plane rather than a concrete surface, and no cover is measurable against it.",
  "footing.cad.assumption.sampler": "Bar extents and interface crossings were measured on the arc-aware production centreline sampler at a {tolerance} mm chord tolerance, the same path the collision detector follows.",
  "footing.cad.assumption.columnBaseAbove": "In the analysis model the base Nút of column Phần tử {Phần tử} sits at z = {base} m, which is {gap} m above the footing top at z = {top} m. The stub is taken from the footing top, because that is the elevation the production dowel and starter geometry was placed against.",
  "footing.cad.assumption.aggregate": "No concrete in the project states a maximum aggregate size, so {mm} mm is assumed. It is not a regulatory default.",
  "footing.cad.refusal.footingNotFound": "No footing with id {id}.",
  "footing.cad.refusal.nodeNotFound": "Footing {footing} references Nút {Nút}, which is not in the model.",
  "footing.cad.refusal.noColumn": "Footing {footing} references no column. Without one there is no footprint and no interface, and inventing a column size would move someone’s foundation.",
  "footing.cad.refusal.notDimensioned": "Footing {footing} is not dimensioned. Plan dimensions and thickness must all be positive.",
  "footing.cad.refusal.rotated": "Footing {footing} is rotated {rotation}°. Resolving the connection onto rotated footing axes is not implemented, and treating global axes as local ones would misplace the interface.",
  "footing.cad.refusal.eccentric": "Footing {footing} has plan eccentricity ({b}, {l}) m. The model documents this as the offset of the footing centroid, while the production dowel geometry uses it as the column centre; with a non-zero value those are different places and choosing one would be a guess.",
  "footing.cad.refusal.pedestal": "Footing {footing} has a pedestal. A pedestal is a third concrete component with its own interfaces and is not represented in this release.",
  "footing.cad.refusal.noAssembly": "Footing {footing} has no detailing assembly. Generate foundation detailing first.",
  "footing.cad.refusal.noVerifier": "Footing {footing} has no verifier identity. The handoff certificate would name no verifier, which a consumer cannot tell apart from one that was lost in transit. Run the code check and design so the Các thanh are verified, and regenerate the detailing; if the project regulation changed after that run, the earlier identity no longer applies and the design must be re-run under the regulation now bound.",
  "footing.cad.refusal.noCage": "Footing {footing} has no transfer-cage reinforcement in its assembly.",
  "footing.cad.refusal.noDowels": "Footing {footing} has no column dowels, so there is no transfer cage to Xuất.",
  "footing.cad.refusal.unclassifiedBar": "Footing {footing}: these bars have no reinforcement family this exporter can state — {bars}. Assigning them to an existing family would misdescribe them.",
  "footing.cad.refusal.incompatibleWithV1": "Footing {footing}: the assembly contains {bars} bar(s) in families RcCadHandoffV1 does not declare ({families}). V1 is frozen and carries column dowels and starter ties only; describing those bars as either family would misdescribe them, and omitting them would hide steel that exists. Xuất RcCadHandoffV2, which carries them.",
  "footing.cad.refusal.noStubExtent": "Footing {footing}: the column stub would span from z = {base} m to z = {top} m, which is not a solid.",
  "footing.cad.refusal.stale": "Footing {footing}: the cage was generated against demand revision {generated} and the model is now at {current}. Regenerate the detailing before exporting.",
